/*!  SapphireRWALibrary PROD v0.6.35 2026-08-25T17:00:27.896Z */
(function () {
	var DOCS = {"locale":"<h6>Overview</h6>\n<p>A static utility method that formats a date/time value for display using the browser’s <code>Intl.DateTimeFormat</code> API.</p>\n<p>Use <code>Locale.DateTimeFormat</code> when you need a locale-aware date and/or time string (for example in expressions, labels, or lists) without building formatting options yourself. It respects the app’s current locale from <code>SapphireRWALibrary.State.locale</code> when no locale is passed, and returns a plain <code>Text</code> string ready to show in the UI.</p>\n<ul>\n<li>Pass <code>DateStyle</code> and/or <code>TimeStyle</code> for common presets (<code>full</code>, <code>long</code>, <code>medium</code>, <code>short</code>).</li>\n<li>Use <code>AdditionalOptions</code> to merge any extra <code>Intl.DateTimeFormat</code> options (for example <code>hour12</code>, <code>timeZone</code>, or individual field options).</li>\n<li>On failure (invalid locale or options), the method returns a string starting with <code>ERROR:</code> instead of throwing.</li>\n</ul>\n<hr><h6>Method</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Returns</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>DateTimeFormat</code></td>\n<td><code>Text</code></td>\n<td>Formats <code>DateTime</code> for the given (or current) locale and returns the result.</td>\n</tr>\n</tbody></table>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>DateTime</code></td>\n<td><code>Date</code></td>\n<td>The date/time to format. If empty, the current date/time (<code>new Date()</code>) is used.</td>\n</tr>\n<tr>\n<td><code>Locale</code></td>\n<td><code>Text</code></td>\n<td>BCP 47 locale code (for example <code>en-US</code>, <code>pt-PT</code>). If empty, falls back to <code>SapphireRWALibrary.State.locale</code>.</td>\n</tr>\n<tr>\n<td><code>DateStyle</code></td>\n<td><code>Text</code></td>\n<td>Optional date preset passed to <code>Intl.DateTimeFormat</code>. Supported values: <code>full</code>, <code>long</code>, <code>medium</code>, <code>short</code>. Omit to leave the date part unset.</td>\n</tr>\n<tr>\n<td><code>TimeStyle</code></td>\n<td><code>Text</code></td>\n<td>Optional time preset passed to <code>Intl.DateTimeFormat</code>. Supported values: <code>full</code>, <code>long</code>, <code>medium</code>, <code>short</code>. Omit to leave the time part unset.</td>\n</tr>\n<tr>\n<td><code>Options</code></td>\n<td><code>DateTimeFormatOptions</code></td>\n<td>Optional object merged into the formatter options after <code>DateStyle</code> / <code>TimeStyle</code>. Use for advanced <code>Intl.DateTimeFormat</code> settings not covered by the style presets.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>DateTimeFormatOptions</code> structure</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>weekday</code></td>\n<td><code>Text</code></td>\n<td>Weekday representation. Supported values: <code>long</code> (<code>Monday</code>), <code>short</code> (<code>Mon</code>), <code>narrow</code> (<code>M</code>).</td>\n</tr>\n<tr>\n<td><code>day</code></td>\n<td><code>Text</code></td>\n<td>Day of the month. Supported values: <code>numeric</code> (<code>1</code>), <code>2-digit</code> (<code>01</code>).</td>\n</tr>\n<tr>\n<td><code>month</code></td>\n<td><code>Text</code></td>\n<td>Month representation. Supported values: <code>numeric</code> (<code>3</code>), <code>2-digit</code> (<code>03</code>), <code>long</code> (<code>March</code>), <code>short</code> (<code>Mar</code>), <code>narrow</code> (<code>M</code>).</td>\n</tr>\n<tr>\n<td><code>year</code></td>\n<td><code>Text</code></td>\n<td>Year representation. Supported values: <code>numeric</code> (<code>2026</code>), <code>2-digit</code> (<code>26</code>).</td>\n</tr>\n<tr>\n<td><code>hour12</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, uses a 12-hour clock (AM/PM); when <code>False</code>, uses 24-hour. If omitted, follows the locale default.</td>\n</tr>\n<tr>\n<td><code>timeZone</code></td>\n<td><code>Text</code></td>\n<td>IANA time zone to format in (for example <code>UTC</code>, <code>Europe/Lisbon</code>, <code>America/New_York</code>). Defaults to the browser/device time zone when omitted.</td>\n</tr>\n<tr>\n<td><code>timeZoneName</code></td>\n<td><code>Text</code></td>\n<td>How the time zone is labeled. Supported values: <code>short</code>, <code>long</code>, <code>shortOffset</code>, <code>longOffset</code>, <code>shortGeneric</code>, <code>longGeneric</code> (for example <code>GMT</code>, <code>Pacific Standard Time</code>, <code>GMT-8</code>).</td>\n</tr>\n<tr>\n<td><code>hour</code></td>\n<td><code>Text</code></td>\n<td>Hour field. Supported values: <code>numeric</code> (<code>1</code> or <code>13</code>), <code>2-digit</code> (<code>01</code> or <code>13</code>).</td>\n</tr>\n<tr>\n<td><code>minute</code></td>\n<td><code>Text</code></td>\n<td>Minute field. Supported values: <code>numeric</code> (<code>1</code>), <code>2-digit</code> (<code>01</code>).</td>\n</tr>\n<tr>\n<td><code>second</code></td>\n<td><code>Text</code></td>\n<td>Second field. Supported values: <code>numeric</code> (<code>1</code>), <code>2-digit</code> (<code>01</code>).</td>\n</tr>\n</tbody></table>\n<hr><h6>Return value</h6>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Text</code></td>\n<td>The formatted date/time string for the resolved locale and options, or <code>ERROR: …</code> with the failure message.</td>\n</tr>\n</tbody></table>\n<hr><h6>Notes</h6>\n<ul>\n<li>At least one of <code>DateStyle</code>, <code>TimeStyle</code>, or meaningful <code>Options</code> should be provided; otherwise the formatter may use the browser default and the result can vary.</li>\n<li><code>Options</code> overrides conflicting keys from <code>DateStyle</code> / <code>TimeStyle</code> because it is applied last via <code>Object.assign</code>.</li>\n<li>This is not a UI component: call it from client actions or expressions whenever you need a localized date/time string.</li>\n</ul>","checkboxlabel":"<h6>Overview</h6>\n<p>A styling helper that combines a platform <code>Checkbox</code> with a matching <code>Label</code> into a consistent inline layout.</p>\n<ul>\n<li>Renders as an <code>inline-flex</code> row with an 8px gap between the checkbox and the label.</li>\n<li>Applies a <code>pointer</code> cursor to the label area for better affordance.</li>\n<li>When the wrapped checkbox is a small input (<code>input.small</code>), it adds a 4px top padding to align the checkbox vertically.</li>\n</ul>\n<p>The helper does not create the checkbox or the label content itself. You provide both via placeholders.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the helper container (used by the platform to size the inline-flex wrapper).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Checkbox</code></td>\n<td>The platform checkbox input/markup to display.</td>\n</tr>\n<tr>\n<td><code>Label</code></td>\n<td>The label text/markup associated with the checkbox.</td>\n</tr>\n</tbody></table>","filterbar":"<h6>Overview</h6>\n<p>A layout helper that wraps filter UI content into a horizontal bar. When <code>IsSticky</code> is enabled, the helper measures its own dimensions and uses a placeholder to prevent layout jump while the bar is fixed.</p>\n<ul>\n<li>Places the provided <code>Content</code> and <code>Actions</code> inside the bar wrapper.</li>\n<li>When <code>IsSticky</code> is <code>True</code>, the bar becomes fixed (<code>position: fixed</code>) and keeps its original width while the page scrolls.</li>\n<li>The helper sets CSS variables (<code>--filterbar-top</code>, <code>--filterbar-width</code>, <code>--filterbar-height</code>) to support fixed positioning and the spacing placeholder.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>IsSticky</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, sets <code>data-isfixed=&quot;true&quot;</code> so the bar is fixed and the layout placeholder reserves space during scroll.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Actions</code></td>\n<td>Optional area for filter actions (buttons, menus, etc.) displayed in the bar header.</td>\n</tr>\n<tr>\n<td><code>Content</code></td>\n<td>The main filter UI/content rendered inside the bar.</td>\n</tr>\n</tbody></table>","inputwrapper":"<h6>Overview</h6>\n<p>A layout helper that wraps a platform <code>Input</code> placed in a placeholder. The input itself is not part of the helper: <code>InputWrapper</code> only augments the native field with optional clear behaviour, a leading icon, sizing, and alignment through CSS and JavaScript.</p>\n<ul>\n<li>Place a Service Studio native <code>Input</code> in the <code>Input</code> placeholder. The helper finds that input at runtime and wires behaviour around it.</li>\n<li>When <code>HasClear</code> is <code>True</code> and the field has content, a clear control is shown beside the input; activating it (click or <code>Enter</code> / <code>Space</code>) fires <code>Clear</code>. The consumer is responsible for clearing the input value.</li>\n<li>When <code>IconName</code> is set, a leading icon is rendered at the start of the input.</li>\n<li><code>AlignToEnd</code> flips the input text alignment to the end edge (logical; respects RTL).</li>\n<li><code>Size</code> and <code>Width</code> control the field’s height / padding presets and container width.</li>\n<li>While <code>Enabled</code> is <code>False</code>, the input looks and behaves disabled and the clear control does not fire <code>Clear</code>.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>AlignToEnd</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, aligns the input text to the end edge (<code>text-align: end</code>). When <code>False</code>, text aligns to the start.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the field. When <code>False</code>, applies disabled styling, blocks input interaction, and disables clear.</td>\n</tr>\n<tr>\n<td><code>HasClear</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a clear control while the wrapped input has content.</td>\n</tr>\n<tr>\n<td><code>IconName</code></td>\n<td><code>Text</code></td>\n<td>Optional leading icon name. Empty string hides the icon.</td>\n</tr>\n<tr>\n<td><code>Size</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Height / padding preset for the input. Supported overrides: <code>xs</code>, <code>s</code>. Other values keep the platform default size.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the wrapper (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Input</code></td>\n<td>The platform input to enhance. Not owned by the helper; observed at runtime.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Clear</code></td>\n<td>Fired when the clear control is activated (click or <code>Enter</code> / <code>Space</code>). Clear the input value in the handler.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n</tbody></table>","labelvalue":"<h6>Overview</h6>\n<p>A layout helper for form fields. It arranges a label, a control, and an optional hint into a consistent structure: the label sits beside or above the control, and the hint is rendered below the control inside the value area.</p>\n<p>The <code>LabelValue</code> helper does not own field logic or validation. It only handles presentation and accessibility: when the <code>Value</code> placeholder contains an input or checkbox with an <code>id</code>, the label text is wrapped in a <code>&lt;label for=&quot;…&quot;&gt;</code> so activating the label focuses the control.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>IsMandatory</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, appends a red asterisk (<code>*</code>) after the label text.</td>\n</tr>\n<tr>\n<td><code>LabelTopPadding</code></td>\n<td><code>Integer</code></td>\n<td>Top padding applied to the label in horizontal orientation, in pixels. Used to align the label with the control. Defaults to platform value.</td>\n</tr>\n<tr>\n<td><code>LabelWidth</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Fixed width of the label column when <code>Orientation</code> is <code>horizontal</code>. Ignored in vertical orientation.</td>\n</tr>\n<tr>\n<td><code>Orientation</code></td>\n<td><code>Text</code></td>\n<td>Layout direction: <code>horizontal</code> places the label and control side by side; <code>vertical</code> stacks the label above the control.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Hint</code></td>\n<td>Optional helper text shown below the control.</td>\n</tr>\n<tr>\n<td><code>Label</code></td>\n<td>Label text displayed next to or above the control.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td>The form control or read-only content associated with the label.</td>\n</tr>\n</tbody></table>","tablewrapper":"<h6>Overview</h6>\n<p>A layout helper that wraps a platform <code>Table</code> (or equivalent markup) placed in a placeholder. The table itself is not part of the helper: <code>TableWrapper</code> only controls scroll behaviour, sticky headers, loading, empty state, optional clickable rows, optional reorderable rows, and column width rules through CSS and JavaScript.</p>\n<ul>\n<li>The root (<code>.tablewrapper</code>) is the horizontal scroll container. When <code>MaxHeight</code> is set, it also becomes the vertical scroll container and pins the header cells (and pagination, when present) with <code>position: sticky</code>.</li>\n<li><code>IsStickyHeader</code> enables a cloned header row that sticks to the top of the screen layout while the page scrolls. It is ignored when <code>MaxHeight</code> is set (internal scroll takes over).</li>\n<li>While <code>IsLoading</code> is <code>True</code>, the table is dimmed and a centered loading overlay is shown over the wrapper.</li>\n<li>When <code>PageCount</code> is <code>0</code> and the wrapper is no longer pristine, the <strong>NoRecords</strong> placeholder is shown. <code>IsPristine</code> keeps the empty state hidden before the first data load.</li>\n<li><code>ColumnFixedWidths</code> applies fixed <code>table-layout</code> and honours <code>width-*</code> classes on cells; when off, those width classes are cleared.</li>\n<li>When <code>ClickableRows</code> is <code>True</code>, body rows become clickable and fire <code>RowClick</code> with the first <code>data-rowid</code> found on a cell in that row. When no cell has <code>data-rowid</code>, the event receives <code>&quot;missing rowid&quot;</code>. Clicks on interactive cell content (<code>a</code>, <code>button</code>, <code>input</code>, <code>select</code>, <code>textarea</code>, <code>label</code>, and common ARIA / editable roles) do not fire <code>RowClick</code>. Turning <code>ClickableRows</code> off removes the handlers.</li>\n<li>When <code>ReorderableRows</code> is <code>True</code>, every <code>tbody &gt; tr</code> in the wrapped table can be dragged to a new position (hover cursor is <code>grab</code>). After a drop that changes order, <code>RowsReordered</code> fires with the <code>data-rowid</code> of each row in the new visual order (JSON array string). Interactive cell content does not start a drag. A completed drag does not fire <code>RowClick</code>.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ClickableRows</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, makes body rows clickable and fires <code>RowClick</code> with the row id from the first <code>td[data-rowid]</code>. Interactive cell content does not trigger <code>RowClick</code>. When <code>False</code>, click handlers are removed.</td>\n</tr>\n<tr>\n<td><code>ColumnFixedWidths</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, uses fixed table layout and applies <code>width-*</code> size classes to columns. When <code>False</code>, those width classes are unset.</td>\n</tr>\n<tr>\n<td><code>Density</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireDensity\"><code>SapphireDensity</code></a></td>\n<td></td>\n</tr>\n<tr>\n<td><code>HasPagination</code></td>\n<td><code>Boolean</code></td>\n<td></td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Integer</code></td>\n<td>Fixed height of the wrapper in pixels. When <code>0</code> / unset, height is not forced.</td>\n</tr>\n<tr>\n<td><code>IsLoading</code></td>\n<td><code>Boolean</code></td>\n<td>Shows a centered loading overlay and dims the table. Clearing loading also exits the pristine state.</td>\n</tr>\n<tr>\n<td><code>IsPristine</code></td>\n<td><code>Boolean</code></td>\n<td>Marks the initial / untouched state. While pristine, an empty <code>PageCount</code> does not show the no-records UI.</td>\n</tr>\n<tr>\n<td><code>IsStickyHeader</code></td>\n<td><code>Boolean</code></td>\n<td>Pins a cloned header to the top of the screen layout on vertical page scroll. Disabled automatically when <code>MaxHeight</code> is set.</td>\n</tr>\n<tr>\n<td><code>MaxHeight</code></td>\n<td><code>Integer</code></td>\n<td>Maximum height of the wrapper in pixels. When greater than <code>0</code>, enables internal vertical scroll with a sticky header (and sticky pagination). When <code>0</code>, no max-height.</td>\n</tr>\n<tr>\n<td><code>MaxRecords</code></td>\n<td><code>Integer</code></td>\n<td>For pagination: Number of records per page</td>\n</tr>\n<tr>\n<td><code>PageCount</code></td>\n<td><code>Integer</code></td>\n<td>Record length for the current page. When 0 it displays the NoRecords placeholder. Otherwise, its always hidden</td>\n</tr>\n<tr>\n<td><code>ReorderableRows</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, body rows (<code>tbody &gt; tr</code>) can be dragged to reorder. Hover shows a grab cursor. After a drop that changes order, <code>RowsReordered</code> fires with each row&#39;s <code>data-rowid</code> in the new order. Interactive cell content does not start a drag.</td>\n</tr>\n<tr>\n<td><code>StartIndex</code></td>\n<td><code>Integer</code></td>\n<td>For pagination: Set the initial index to start pagination</td>\n</tr>\n<tr>\n<td><code>TotalCount</code></td>\n<td><code>Long Integer</code></td>\n<td>For pagination: Total records of list</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Table</code></td>\n<td>The platform table to enhance. Not owned by the helper; styled and observed at runtime.</td>\n</tr>\n<tr>\n<td><code>NoRecords</code></td>\n<td>Empty-state content shown when there are no records after the first load (<code>PageCount</code> is <code>0</code> and not <code>IsPristine</code>).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>PaginationNavigate</code></td>\n<td>Event triggered on navigate. New start index value returned.</td>\n<td><code>NewStartIndex</code> (<code>Integer</code>)</td>\n</tr>\n<tr>\n<td><code>RowClick</code></td>\n<td>Fired when a clickable row is activated (not when the click target is interactive cell content). Provide a <code>data-rowid</code> on at least one <code>td</code> in the row; otherwise the argument is <code>&quot;missing rowid&quot;</code>.</td>\n<td><code>RowId</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>RowsReordered</code></td>\n<td>Fired after a row is dropped in a new position. Each id is the row&#39;s <code>data-rowid</code> (copied from the first <code>td[data-rowid]</code> when present). JSON array string, e.g. <code>[&quot;id-1&quot;,&quot;id-2&quot;]</code>.</td>\n<td><code>RowIds</code> (<code>Text</code>)</td>\n</tr>\n</tbody></table>","responsivegrid":"<h6>Overview</h6>\n<p>A CSS Grid layout that arranges its children into responsive columns. By default it auto-fits as many columns as fit the available width given a minimum column size; you can also force a fixed column count.</p>\n<ul>\n<li>The root (<code>.responsive-grid</code>) is a CSS Grid. Column sizing uses <code>minmax(MinColWidth, 1fr)</code> with <code>auto-fit</code>, so the number of columns grows or shrinks with the container width.</li>\n<li>When <code>ForcedColumns</code> is greater than <code>0</code>, the grid uses that exact column count instead of <code>auto-fit</code>.</li>\n<li><code>GridGap</code> sets the gap between cells (in pixels). <code>MaxColWidth</code>, when greater than <code>0</code>, caps each item&#39;s maximum width.</li>\n<li>Direct children of the content placeholder become grid items (<code>.responsive-grid-item</code>). Nested <code>.card-basic</code> elements stretch to the full item height.</li>\n<li>If the placeholder contains a single OutSystems List (<code>.list.list-group</code>), the list wrapper is unwrapped with <code>display-contents</code> so each list row becomes a grid item instead of the list itself.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ForcedColumns</code></td>\n<td><code>Integer</code></td>\n<td>Fixed number of columns. When <code>0</code> (or unset), columns are auto-fitted from <code>MinColWidth</code>. When <code>&gt; 0</code>, that many columns are always used.</td>\n</tr>\n<tr>\n<td><code>GridGap</code></td>\n<td><code>Integer</code></td>\n<td>Gap between grid cells, in pixels.</td>\n</tr>\n<tr>\n<td><code>MaxColWidth</code></td>\n<td><code>Integer</code></td>\n<td>Maximum width of each grid item, in pixels. When <code>0</code> (or unset), items have no max-width cap.</td>\n</tr>\n<tr>\n<td><code>MinColWidth</code></td>\n<td><code>Integer</code></td>\n<td>Minimum width used for column sizing (<code>minmax</code>), in pixels. Drives how many columns fit when <code>ForcedColumns</code> is <code>0</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Containers</code></td>\n<td>Elements to place in the grid. Each direct child becomes a cell. A single List inside is unwrapped so its rows are the cells.</td>\n</tr>\n</tbody></table>","sapphirepopupcontent":"<h6>Overview</h6>\n<p>Structured content layout for the <strong>Popup</strong> widget from Service Studio. Use it when you need a dialog with a header, a scrollable body, an optional three-column footer, and an optional close button — without the built-in title, message, and action buttons of <code>ActionPopup</code>.</p>\n<ul>\n<li>The component renders a vertical flex layout: <strong>Header</strong> (fixed), <strong>Body</strong> (scrollable), and <strong>Footer</strong> (fixed, three columns).</li>\n<li>On initialization, focus moves into the popup content so keyboard users can interact immediately.</li>\n<li>The dialog is capped at <code>calc(100vh - 48px)</code>; when content exceeds that height, only the <strong>Body</strong> scrolls.</li>\n<li>Empty <strong>Header</strong> and <strong>Body</strong> placeholders are hidden. The <strong>Footer</strong> is hidden when all three footer placeholders are empty.</li>\n<li>When <code>HasClose</code> is <code>True</code>, a close button is shown in the top-right corner and the <strong>Header</strong> keeps a minimum height even when empty, so the close button does not overlap the body.</li>\n<li>When <code>HasSeparators</code> is <code>True</code>, horizontal separators are drawn between the header and body and between the body and footer.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CloseOnEsc</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, pressing <code>Escape</code> fires the <code>Close</code> event.</td>\n</tr>\n<tr>\n<td><code>HasClose</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the top-right close button and reserves header space for it. When <code>False</code>, the close button is hidden.</td>\n</tr>\n<tr>\n<td><code>HasSeparators</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, draws separators between the header/body and body/footer sections.</td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Integer</code></td>\n<td>Fixed height of the popup content in pixels. When <code>0</code>, height grows with content (still limited by the viewport max-height).</td>\n</tr>\n<tr>\n<td><code>MinHeight</code></td>\n<td><code>Integer</code></td>\n<td>Minimum height of the popup content in pixels. When <code>0</code>, no minimum is applied.</td>\n</tr>\n<tr>\n<td><code>Padding</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Spacing preset for the dialog padding and section gaps. Supported values: <code>none</code>, <code>s</code>, <code>base</code>, <code>m</code>, <code>l</code>, <code>xl</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the dialog. Supported values: <code>s</code> (400px), <code>m</code> (600px), <code>l</code> (960px, default), <code>xl</code> (1200px), <code>full</code> (viewport minus 48px).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Header</code></td>\n<td>Top section for a title or custom content. Rendered with heading-4 typography. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Body</code></td>\n<td>Main scrollable content area. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>FooterLeft</code></td>\n<td>Left-aligned content in the footer grid (e.g. secondary actions).</td>\n</tr>\n<tr>\n<td><code>FooterCenter</code></td>\n<td>Center-aligned content in the footer grid.</td>\n</tr>\n<tr>\n<td><code>FooterRight</code></td>\n<td>Right-aligned content in the footer grid (e.g. primary actions).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Close</code></td>\n<td>Fired when the close button is clicked or when <code>Escape</code> is pressed while <code>CloseOnEsc</code> is <code>True</code>.</td>\n</tr>\n</tbody></table>","scrollablecontent":"<h6>Overview</h6>\n<p>A vertical content layout with a fixed header, a scrollable body, and an optional three-column footer. Use it when you need a constrained-height region where only the body scrolls — for example inside overlays, side panels, or custom dialogs.</p>\n<ul>\n<li>The component renders a vertical flex layout: <strong>Header</strong> (fixed), <strong>Body</strong> (scrollable), and <strong>Footer</strong> (fixed, three columns).</li>\n<li><code>Height</code> and <code>MaxHeight</code> set the container size in pixels. When content exceeds the available height, only the <strong>Body</strong> scrolls.</li>\n<li>The body uses a thin scrollbar with a stable gutter so layout does not shift when the scrollbar appears.</li>\n<li>An empty <strong>Header</strong> is hidden. The <strong>Footer</strong> stays in the layout as a three-column grid (<code>FooterLeft</code> / <code>FooterCenter</code> / <code>FooterRight</code>).</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the component visually / interactively as configured in the widget.</td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Text</code></td>\n<td>Fixed height of the container in pixels. When empty / unset, height is not forced and content can grow naturally.</td>\n</tr>\n<tr>\n<td><code>MaxHeight</code></td>\n<td><code>Integer</code></td>\n<td>Maximum height of the container in pixels. When <code>0</code>, no max-height is applied.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the container (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Header</code></td>\n<td>Top section for a title or custom content. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Body</code></td>\n<td>Main scrollable content area. Grows to fill remaining space between header and footer.</td>\n</tr>\n<tr>\n<td><code>FooterLeft</code></td>\n<td>Left-aligned content in the footer grid (e.g. secondary actions).</td>\n</tr>\n<tr>\n<td><code>FooterCenter</code></td>\n<td>Center-aligned content in the footer grid.</td>\n</tr>\n<tr>\n<td><code>FooterRight</code></td>\n<td>Right-aligned content in the footer grid (e.g. primary actions).</td>\n</tr>\n</tbody></table>","sidebar":"<h6>Overview</h6>\n<p>This component is a wrapper containing the <code>Interaction\\Sidebar</code> component from OSUI.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>HasOverlay</code></td>\n<td><code>Boolean</code></td>\n<td>Set to True, to show an overlay when the Sidebar is open. When you click on the overlay, the Sidebar is closed.</td>\n</tr>\n<tr>\n<td><code>IsOpen</code></td>\n<td><code>Boolean</code></td>\n<td>Controls visibility of the sidebar.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Spacing preset for the sidebar width. Defaults to <code>xl2</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n<tr>\n<td><code>Header</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n</tbody></table>","actionpopup":"<h6>Overview</h6>\n<p>A modal action popup with a backdrop that blocks interaction with the page. It renders a title, a message, optional custom content (via the <code>Content</code> placeholder), a close button in the top-right corner, and up to three action buttons: Cancel, Negative and Positive.</p>\n<ul>\n<li>When a button label is &quot;&quot;, that button is not displayed.</li>\n<li>The Positive button always shows a <code>check-bold</code> icon before its label.</li>\n<li>Visibility is driven by the <code>IsOpen</code> input. On open, the dialog is teleported to <code>&lt;body&gt;</code>, page scroll is locked, focus moves into the dialog and Tab is trapped inside it.</li>\n<li>The close button (top-right) is only rendered when <code>HasClose</code> is <code>True</code>. The <code>Escape</code> key closes the popup only when <code>HasClose</code> AND <code>CloseOnEsc</code> are both <code>True</code>; when <code>HasClose</code> is <code>False</code> the popup can only be dismissed through the action buttons. Both the close button and <code>Escape</code> trigger the <code>Cancel</code> event. Clicking the backdrop never closes it.</li>\n<li>The Cancel / Negative / Positive buttons raise their respective events and then close the popup.</li>\n<li>The <code>Close</code> event fires whenever the popup closes, regardless of the trigger (any button, the close icon, <code>Escape</code>, or <code>IsOpen</code> being set to <code>False</code>). It is emitted after the specific button event.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CloseOnEsc</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code> (and <code>HasClose</code> is <code>True</code>), pressing <code>Escape</code> closes the popup (fires <code>Cancel</code>).</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the Cancel / Negative / Positive action buttons. When <code>False</code>, those buttons are disabled and ignore clicks; the close button and <code>Escape</code> still work.</td>\n</tr>\n<tr>\n<td><code>HasClose</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the top-right close button. When <code>False</code>, hides it and disables the <code>Escape</code> shortcut, so the popup is only dismissible via the action buttons.</td>\n</tr>\n<tr>\n<td><code>IsOpen</code></td>\n<td><code>Boolean</code></td>\n<td>Controls visibility of the popup.</td>\n</tr>\n<tr>\n<td><code>LabelCancel</code></td>\n<td><code>Text</code></td>\n<td>Label on the cancel button. Button hidden when &quot;&quot;.</td>\n</tr>\n<tr>\n<td><code>LabelNo</code></td>\n<td><code>Text</code></td>\n<td>Label on the negative button. Button hidden when &quot;&quot;.</td>\n</tr>\n<tr>\n<td><code>LabelYes</code></td>\n<td><code>Text</code></td>\n<td>Label on the affirmative button. Button hidden when &quot;&quot;.</td>\n</tr>\n<tr>\n<td><code>Message</code></td>\n<td><code>Text</code></td>\n<td>Message of the popup. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Padding</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Spacing preset for the dialog sections. Defaults to <code>m</code>.</td>\n</tr>\n<tr>\n<td><code>Title</code></td>\n<td><code>Text</code></td>\n<td>Title of the popup. Hidden when empty.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Spacing preset for the dialog width. Defaults to <code>m</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Placeholder for custom content.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Cancel</code></td>\n<td>Fired when the Cancel button is clicked, or when the close button / <code>Escape</code> dismisses the popup. The popup then closes.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>Close</code></td>\n<td>Fired whenever the popup closes, after any preceding button event (<code>Cancel</code> / <code>No</code> / <code>Yes</code>), including when <code>IsOpen</code> becomes <code>False</code>.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>No</code></td>\n<td>Fired when the Negative button is clicked. The popup then closes.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>Yes</code></td>\n<td>Fired when the Positive button is clicked. The popup then closes.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n</tbody></table>","badge":"<h6>Overview</h6>\n<p>A compact status label for short text such as a category, state, or tag. It is a presentation-only component: color, optional leading status dot, and corner shape are driven by inputs; the label content comes from the <code>Content</code> placeholder.</p>\n<ul>\n<li>Default shape is a pill (<code>border-radius: 999px</code>). Use <code>Shape</code> to switch to rounded (<code>soft</code>) or square (<code>none</code>) corners.</li>\n<li>When <code>HasDot</code> is <code>True</code>, a small colored circle is rendered before the content, matching the selected <code>Color</code>.</li>\n<li>Color themes map to semantic surfaces: <code>neutral</code>, <code>info</code>, <code>success</code>, <code>warning</code>, and <code>error</code>.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Color</code></td>\n<td><code>SapphireColor</code></td>\n<td>Semantic color theme. Supported values: <code>neutral</code>, <code>info</code>, <code>success</code>, <code>warning</code>, <code>error</code>.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the badge visually / interactively as configured in the widget.</td>\n</tr>\n<tr>\n<td><code>HasDot</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a leading status dot tinted to match <code>Color</code>.</td>\n</tr>\n<tr>\n<td><code>Shape</code></td>\n<td><code>Shape</code></td>\n<td>Corner style. Omit or leave default for a pill; <code>soft</code> uses a small radius; <code>none</code> removes rounding.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the badge container (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Text or markup displayed inside the badge.</td>\n</tr>\n</tbody></table>","buttondropdown":"<h6>Overview</h6>\n<p>A button that reveals a dropdown panel of actions. It supports two modes: a regular button whose label toggles the panel, and a split button where the label runs its own <code>Click</code> action while a dedicated chevron opens the panel.</p>\n<ul>\n<li>In regular mode the label is the trigger: activating it (click or <code>Enter</code>/<code>Space</code>, <code>ArrowDown</code> to open) toggles the panel.</li>\n<li>In split-button mode a chevron is appended after the label and becomes the trigger; the label instead fires the <code>Click</code> event.</li>\n<li>The panel closes when a menu action (link or button) is activated, on <code>Escape</code>, or on click outside. Form controls inside the panel do not close it.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ButtonClass</code></td>\n<td><code>Text</code></td>\n<td>Allows to style the button to the existing semantic versions.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables all interaction. Disabled dropdowns close any open panel.</td>\n</tr>\n<tr>\n<td><code>IsSplitButton</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders a separate chevron trigger and the label fires <code>Click</code> instead of opening.</td>\n</tr>\n<tr>\n<td><code>IsValid</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, marks the component invalid and shows <code>ValidationMessage</code> below it.</td>\n</tr>\n<tr>\n<td><code>Placement</code></td>\n<td><code>Text</code></td>\n<td>Preferred placement of the actions panel relative to the trigger. Defaults to <code>bottom-start</code>.</td>\n</tr>\n<tr>\n<td><code>ValidationMessage</code></td>\n<td><code>Text</code></td>\n<td>Message shown below the widget while <code>IsValid</code> is <code>False</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Sets the width of the component.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Label</code></td>\n<td>Element that acts as the button label / trigger.</td>\n</tr>\n<tr>\n<td><code>Actions</code></td>\n<td>Content of the dropdown panel (menu links or buttons).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Click</code></td>\n<td>Fired when the label is activated in split-button mode (click or <code>Enter</code>/<code>Space</code>).</td>\n</tr>\n</tbody></table>","chip":"<h6>Overview</h6>\n<p>A compact, interactive element used to represent an attribute, filter, selection, or action. Chips can be clickable, selectable (toggle), and optionally include a leading icon and a clear button.</p>\n<p>The <code>Chip</code> enhances a root element containing a <code>.chip-content</code> node. Based on its configuration it wires up click, toggle, and clear interactions, reflects its state through <code>data-*</code> attributes, and manages the appropriate ARIA roles and keyboard support.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables all interaction. Disabled chips are not focusable.</td>\n</tr>\n<tr>\n<td><code>HasClear</code></td>\n<td><code>Boolean</code></td>\n<td>Renders a trailing clear button.</td>\n</tr>\n<tr>\n<td><code>Icon</code></td>\n<td><code>Text</code></td>\n<td>Optional leading icon name rendered before the content.</td>\n</tr>\n<tr>\n<td><code>IsClickable</code></td>\n<td><code>Boolean</code></td>\n<td>Makes the whole chip act as a button firing <code>Click</code>.</td>\n</tr>\n<tr>\n<td><code>IsSelectable</code></td>\n<td><code>Boolean</code></td>\n<td>Makes the chip a toggle that fires <code>Toggle</code> and tracks selected state.</td>\n</tr>\n<tr>\n<td><code>IsSelected</code></td>\n<td><code>Boolean</code></td>\n<td>Initial selected state (only meaningful when <code>IsSelectable</code>).</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Element to be displayed as content.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Clear</code></td>\n<td>Fired when the clear button is activated.</td>\n</tr>\n<tr>\n<td><code>Click</code></td>\n<td>Fired when a clickable chip is activated (click or <code>Enter</code>/<code>Space</code>).</td>\n</tr>\n<tr>\n<td><code>Toggle</code></td>\n<td>Fired when a selectable chip is toggled; receives the new selected state.</td>\n</tr>\n</tbody></table>","colorpicker":"<h6>Overview</h6>\n<p>A compact HSV color picker. The host shows a swatch of the committed color; activating it opens a Tippy overlay with a saturation/brightness plane, a hue slider, an optional hex field, and Cancel / Apply actions.</p>\n<ul>\n<li>The overlay is a draft: dragging the plane or slider, or typing a hex value, updates the preview only. Nothing is emitted until <strong>Apply</strong>.</li>\n<li>The preview swatch is split: <strong>left</strong> is the current committed color, <strong>right</strong> is the color being selected. Empty sides show a checkerboard.</li>\n<li><strong>Cancel</strong>, <code>Escape</code>, clicking the trigger again, or clicking outside discards the draft and closes the overlay. <code>Change</code> is not fired.</li>\n<li><strong>Apply</strong> normalizes the color to <code>#rrggbb</code> (lowercase), fires <code>Change</code>, and closes the overlay.</li>\n<li><code>Value</code> seeds the committed color on init and via <code>parametersChanged</code>. <code>#rgb</code> and <code>#rrggbb</code> (with or without <code>#</code>) are accepted; malformed values are treated as empty.</li>\n<li>When <code>ShowInput</code> is <code>True</code>, the hex field is editable. Typing is normalized to lowercase <code>#</code> + hex digits; a complete value is always <code>#rrggbb</code> (3-digit <code>#rgb</code> expands on paste, blur, or Apply). <code>Enter</code> in the field is the same as Apply.</li>\n<li>When <code>AllowEmpty</code> is <code>False</code>, an empty (or malformed) hex cannot be applied and the input is marked invalid. When <code>True</code>, a <strong>Clear</strong> button sits between Cancel and Apply: it commits an empty value, fires <code>Change</code>, and closes the overlay. Apply may also emit an empty string.</li>\n<li>Without the hex field (<code>ShowInput</code> = <code>False</code>), Apply always emits the color from the HSV plane.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>AllowEmpty</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, Apply cannot emit an empty value, the hex input is styled invalid while empty or malformed, and Clear is hidden. When <code>True</code>, Clear commits an empty value (fires <code>Change</code> and closes). Apply may also emit an empty string.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables interaction. Disabled pickers ignore clicks and close any open overlay without emitting.</td>\n</tr>\n<tr>\n<td><code>ShowInput</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows an editable hex field in the overlay. When <code>False</code>, color can only be chosen from the HSV plane.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td><code>Text</code></td>\n<td>Committed hexadecimal color (<code>#rrggbb</code> or <code>#rgb</code>). Empty means no color. Updates while the overlay is closed refresh the trigger; an open draft is not overwritten.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Change</code></td>\n<td>Fired when Apply is pressed with a valid color, or when Clear commits an empty value (<code>AllowEmpty</code> is <code>True</code>).</td>\n<td><code>Identifier</code> (<code>Text</code>), <code>Value</code> (<code>Text</code>)</td>\n</tr>\n</tbody></table>","overlay":"<h6>Overview</h6>\n<p>A floating overlay (popover / tooltip / dropdown surface) built on top of Tippy. It anchors content to a trigger element and handles positioning, focus management, keyboard navigation, RTL flipping, and optional iframe content.</p>\n<p>The <code>Overlay</code> attaches to a trigger element and shows a floating box containing either inline content, an external element, or an iframe. It supports click and hover triggers, persistent (manually dismissed) overlays, and full keyboard accessibility (Tab trapping, <code>Enter</code>/<code>Space</code> to toggle, <code>Escape</code> to close).</p>\n<p><a target=\"_blank\" href=\"https://atomiks.github.io/tippyjs/v6/all-props/#placement\">Tippy.js placement options</a></p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>ExternalContentId</code></td>\n<td><code>Text</code></td>\n<td>Overrides the <code>Content</code> placeholder with an element defined elsewhere on the page.</td>\n</tr>\n<tr>\n<td><code>ExternalTriggerId</code></td>\n<td><code>Text</code></td>\n<td>Overrides the <code>Trigger</code> placeholder with an element defined elsewhere on the page.</td>\n</tr>\n<tr>\n<td><code>FocusOnClose</code></td>\n<td><code>Boolean</code></td>\n<td>Returns focus to the trigger when the overlay closes.</td>\n</tr>\n<tr>\n<td><code>FocusOnOpen</code></td>\n<td><code>Boolean</code></td>\n<td>Focuses the first focusable element when the overlay opens.</td>\n</tr>\n<tr>\n<td><code>Height</code></td>\n<td><code>Integer</code></td>\n<td>Fixed height in pixels.</td>\n</tr>\n<tr>\n<td><code>IframeURL</code></td>\n<td><code>Text</code></td>\n<td>Renders the overlay content inside an iframe pointing at this URL.</td>\n</tr>\n<tr>\n<td><code>MaxHeight</code></td>\n<td><code>Integer</code></td>\n<td>Maximum height in pixels.</td>\n</tr>\n<tr>\n<td><code>Options</code></td>\n<td><code>TippyTooltipOptions</code></td>\n<td>Tippy options controlling placement and behaviour. See the <code>Options</code> structure below.</td>\n</tr>\n<tr>\n<td><code>Padding</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireSize\"><code>SapphireSize</code></a></td>\n<td>Padding preset applied to the overlay box.</td>\n</tr>\n<tr>\n<td><code>Persistent</code></td>\n<td><code>Boolean</code></td>\n<td>Keeps the overlay open until explicitly closed and adds a close button.</td>\n</tr>\n<tr>\n<td><code>Theme</code></td>\n<td><code>Text</code></td>\n<td>Optional theme: <code>light</code>, <code>success</code>, <code>info</code>, <code>warning</code>, <code>error</code>. Include <code>disable-init</code> to skip auto-initialization, or <code>iframe-auto-size</code> to auto-size iframe content.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><code>Integer</code></td>\n<td>Fixed width in pixels (also raises <code>maxWidth</code> when larger).</td>\n</tr>\n</tbody></table>\n<hr><h6><code>TippyTooltipOptions</code> structure</h6>\n<p>Tippy configuration passed through to the underlying instance.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>placement</code></td>\n<td><code>Text</code></td>\n<td>Position of the overlay relative to the trigger (flipped automatically in RTL). See the Tippy placement link above.</td>\n</tr>\n<tr>\n<td><code>trigger</code></td>\n<td><code>Text</code></td>\n<td>Event(s) that open the overlay, e.g. <code>click</code> or <code>mouseenter focus</code>. Using <code>click</code> enables keyboard toggle.</td>\n</tr>\n<tr>\n<td><code>arrow</code></td>\n<td><code>Boolean</code></td>\n<td>Renders a pointer arrow on the overlay.</td>\n</tr>\n<tr>\n<td><code>delay</code></td>\n<td><code>Structure</code></td>\n<td>Show/hide delays in milliseconds: <code>{ Show, Hide }</code>.</td>\n</tr>\n<tr>\n<td><code>interactive</code></td>\n<td><code>Boolean</code></td>\n<td>Keeps the overlay open while the pointer is over its content.</td>\n</tr>\n<tr>\n<td><code>hideOnClick</code></td>\n<td><code>Boolean</code></td>\n<td>Hides the overlay when clicking outside it.</td>\n</tr>\n<tr>\n<td><code>flip</code></td>\n<td><code>Boolean</code></td>\n<td>Allows flipping to the opposite placement when there is no room. When <code>false</code>, flipping is disabled.</td>\n</tr>\n<tr>\n<td><code>maxWidth</code></td>\n<td><code>Integer</code></td>\n<td>Maximum width in pixels. Non-numeric values resolve to <code>none</code>; overridden by <code>Width</code> when <code>Width</code> is larger.</td>\n</tr>\n<tr>\n<td><code>appendTo</code></td>\n<td><code>Text</code></td>\n<td>Where the overlay is mounted. <code>body</code> appends to <code>&lt;body&gt;</code>; any other value mounts it next to the trigger.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Element to be displayed as content.</td>\n</tr>\n<tr>\n<td><code>Trigger</code></td>\n<td>Element to be used as the trigger.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Hide</code></td>\n<td>Fired when the overlay is hidden.</td>\n</tr>\n<tr>\n<td><code>Show</code></td>\n<td>Fired when the overlay becomes visible.</td>\n</tr>\n</tbody></table>","sapphiredropdown":"<h6>Overview</h6>\n<p>A combobox-style dropdown for selecting one or many options from a list. It supports search (client- or server-side), select-all, chips for selected values, clear, keyboard navigation / typeahead, and a validation message.</p>\n<ul>\n<li>The trigger is a focusable combobox; activating it (click or keyboard) opens a Tippy panel with the options listbox.</li>\n<li>Single select closes the panel after a choice. Multiple select keeps the panel open and toggles options; overflowing labels collapse to a count summary using <code>SelectedOptionsText</code>.</li>\n<li>When <code>Config.Search</code> is <code>True</code>, a search field filters options. Client-side search matches <code>Label</code> / <code>Description</code>; with <code>SearchServerSide</code>, typing emits <code>Search</code> (debounced 300ms) so the parent can refresh <code>OptionsList</code>.</li>\n<li>While <code>IsSearching</code> is <code>True</code>, the list is hidden and a loading spinner is shown (typical for server-side search).</li>\n<li>Scrolling the list near the bottom fires <code>ScrollEnded</code> once per reach (useful for paging more options).</li>\n<li>When <code>IsValid</code> is <code>False</code>, the trigger is marked invalid and <code>ValidationMessage</code> is shown below it.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Config</code></td>\n<td><code>SapphireDropdownConfig</code></td>\n<td>Behaviour and copy for the dropdown. See the structure below.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables interaction. Disabled dropdowns are not focusable / interactive.</td>\n</tr>\n<tr>\n<td><code>IsSearching</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the loading state in the panel and hides the options list.</td>\n</tr>\n<tr>\n<td><code>IsValid</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, marks the component invalid and shows <code>ValidationMessage</code>.</td>\n</tr>\n<tr>\n<td><code>OptionsList</code></td>\n<td><code>SapphireDropdownOption</code></td>\n<td>Available options to render in the list.</td>\n</tr>\n<tr>\n<td><code>SelectedList</code></td>\n<td><code>SapphireDropdownOption</code></td>\n<td>Currently selected options. Single-select keeps at most one entry; missing labels/icons are hydrated from <code>OptionsList</code> when possible.</td>\n</tr>\n<tr>\n<td><code>ValidationMessage</code></td>\n<td><code>Text</code></td>\n<td>Message shown below the trigger while <code>IsValid</code> is <code>False</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the dropdown (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.). The open panel matches the trigger width.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>SapphireDropdownOption</code> structure</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Description</code></td>\n<td><code>Text</code></td>\n<td>Optional secondary text under the label (shown when <code>ShowDescription</code>).</td>\n</tr>\n<tr>\n<td><code>Icon</code></td>\n<td><code>Text</code></td>\n<td>Optional icon name (shown when <code>ShowIcon</code>).</td>\n</tr>\n<tr>\n<td><code>Label</code></td>\n<td><code>Text</code></td>\n<td>Primary text shown in the list, trigger, and chips.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td><code>Text</code></td>\n<td>Stable identifier for the option. Used for selection matching.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>SapphireDropdownConfig</code> structure</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Clear</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a clear control on the trigger while there is a selection.</td>\n</tr>\n<tr>\n<td><code>HasChips</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders selected options as clearable chips below the trigger.</td>\n</tr>\n<tr>\n<td><code>HasSelectAll</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code> and <code>Multiple</code> is <code>True</code>, adds a select-all row at the top of the list.</td>\n</tr>\n<tr>\n<td><code>Multiple</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, allows multiple selections; when <code>False</code>, selecting an option replaces the selection and closes the panel.</td>\n</tr>\n<tr>\n<td><code>Placeholder</code></td>\n<td><code>Text</code></td>\n<td>Trigger text when nothing is selected.</td>\n</tr>\n<tr>\n<td><code>Search</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows the search field in the panel.</td>\n</tr>\n<tr>\n<td><code>SearchServerSide</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, search emits <code>Search</code> for the parent to filter; when <code>False</code>, options are filtered locally.</td>\n</tr>\n<tr>\n<td><code>SearchKeyword</code></td>\n<td><code>Text</code></td>\n<td>Current search keyword (kept in sync with the search input).</td>\n</tr>\n<tr>\n<td><code>SearchPlaceholder</code></td>\n<td><code>Text</code></td>\n<td>Placeholder for the search input.</td>\n</tr>\n<tr>\n<td><code>ShowDescription</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders each option&#39;s <code>Description</code> when present.</td>\n</tr>\n<tr>\n<td><code>ShowIcon</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, renders each option&#39;s <code>Icon</code> when present (list, chips).</td>\n</tr>\n<tr>\n<td><code>NoOptionsText</code></td>\n<td><code>Text</code></td>\n<td>Empty-state message when there are no options.</td>\n</tr>\n<tr>\n<td><code>NoSearchResultsText</code></td>\n<td><code>Text</code></td>\n<td>Empty-state message when search yields no matches.</td>\n</tr>\n<tr>\n<td><code>SelectAllText</code></td>\n<td><code>Text</code></td>\n<td>Label for the select-all row.</td>\n</tr>\n<tr>\n<td><code>SelectedOptionsText</code></td>\n<td><code>Text</code></td>\n<td>Suffix used in the multi-select overflow summary, e.g. <code>&quot;3 selected&quot;</code> when labels do not fit.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Change</code></td>\n<td>Fired when the selection changes.</td>\n<td><code>Identifier</code> (<code>Text</code>), <code>EmittedList</code> (<code>SapphireDropdownOption List</code>)</td>\n</tr>\n<tr>\n<td><code>Clear</code></td>\n<td>Fired when the trigger clear control clears the entire selection (also followed by <code>Change</code>).</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>ScrollEnded</code></td>\n<td>Fired when the options list is scrolled to (near) the bottom; resets when the user scrolls away from the end.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>SearchClear</code></td>\n<td>Fired when the search field is cleared.</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>Search</code></td>\n<td>Fired (debounced) with the current keyword while searching; primarily used with <code>SearchServerSide</code>.</td>\n<td><code>Identifier</code> (<code>Text</code>), <code>EmittedKeyword</code> (<code>Text</code>)</td>\n</tr>\n</tbody></table>","sapphireinput":"<h6>Overview</h6>\n<p>A text / numeric input with optional clear button, leading icon, validation message, and stepper controls. It masks and clamps values according to <code>Type</code> and <code>NumericOptions</code>, and can debounce <code>Change</code> while typing.</p>\n<ul>\n<li><code>Type</code> controls input behaviour: <code>text</code> (free text, start-aligned), <code>integer</code> (digits only), or <code>decimal</code> (digits plus a decimal part limited by <code>DecimalScale</code>).</li>\n<li>For numeric types, display uses a comma as the decimal separator; the internal / emitted value uses a dot.</li>\n<li>When <code>HasSteps</code> is <code>True</code> (numeric types), minus / plus controls appear and <code>ArrowUp</code> / <code>ArrowDown</code> step by <code>Step</code>, respecting <code>Min</code> / <code>Max</code>.</li>\n<li>When <code>HasClear</code> is <code>True</code> and the field has content, a clear control is shown; activating it fires <code>Clear</code> (the consumer typically clears <code>Value</code>).</li>\n<li>On blur (and after the debounce window), the value is remasked, clamped to <code>Min</code>/<code>Max</code>, and <code>Change</code> is emitted if it changed. <code>Enter</code> flushes any pending debounce, commits, then fires <code>EnterKey</code>.</li>\n<li>When <code>IsValid</code> is <code>False</code>, the field is marked invalid and <code>ValidationMessage</code> is shown below it. Externally set values outside type/bounds rules are flagged via <code>data-isoutofbounds</code> (red border) without rewriting the value.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>DebounceChange</code></td>\n<td><code>Integer</code></td>\n<td>Delay in milliseconds before <code>Change</code> fires while typing. <code>0</code> emits on every input. Blur / Enter always flush immediately.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables interaction. Disabled inputs ignore pointer events and use disabled styling.</td>\n</tr>\n<tr>\n<td><code>HasClear</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a clear control while the field has content.</td>\n</tr>\n<tr>\n<td><code>HasSteps</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows minus / plus steppers (intended for numeric types) and enables arrow-key stepping.</td>\n</tr>\n<tr>\n<td><code>IconName</code></td>\n<td><code>Text</code></td>\n<td>Optional leading icon name. Empty string hides the icon and restores default start padding.</td>\n</tr>\n<tr>\n<td><code>IsValid</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>False</code>, marks the field invalid and shows <code>ValidationMessage</code>.</td>\n</tr>\n<tr>\n<td><code>MaxLength</code></td>\n<td><code>Integer</code></td>\n<td>Maximum character length. <code>0</code> (or less) means no limit. Applies to typing and truncates externally set values.</td>\n</tr>\n<tr>\n<td><code>NumericOptions</code></td>\n<td><code>SapphireInputNumericOptions</code></td>\n<td>Bounds and precision for numeric types. See the structure below. Ignored for <code>text</code>.</td>\n</tr>\n<tr>\n<td><code>Placeholder</code></td>\n<td><code>Text</code></td>\n<td>Placeholder text shown when the field is empty.</td>\n</tr>\n<tr>\n<td><code>Type</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireInputType\"><code>SapphireInputType</code></a></td>\n<td>Input mode: <code>text</code>, <code>integer</code>, or <code>decimal</code>.</td>\n</tr>\n<tr>\n<td><code>ValidationMessage</code></td>\n<td><code>Text</code></td>\n<td>Message shown below the field while <code>IsValid</code> is <code>False</code>.</td>\n</tr>\n<tr>\n<td><code>Value</code></td>\n<td><code>Text</code></td>\n<td>Current value. Numeric consumers should treat the emitted value as using <code>.</code> as the decimal separator.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Width preset for the input container (<code>auto</code>, <code>xs</code>–<code>xl7</code>, <code>full</code>, etc.).</td>\n</tr>\n</tbody></table>\n<hr><h6><code>SapphireInputNumericOptions</code> structure</h6>\n<p>Used when <code>Type</code> is <code>integer</code> or <code>decimal</code>. Empty / non-numeric <code>Min</code> or <code>Max</code> mean no bound.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>DecimalScale</code></td>\n<td><code>Integer</code></td>\n<td>Max digits after the decimal for <code>decimal</code> type. <code>0</code> (or with <code>integer</code>) disallows a fractional part.</td>\n</tr>\n<tr>\n<td><code>Max</code></td>\n<td><code>Text</code></td>\n<td>Upper bound. Empty means no maximum. Steppers and commit clamp to this value.</td>\n</tr>\n<tr>\n<td><code>Min</code></td>\n<td><code>Text</code></td>\n<td>Lower bound. Empty means no minimum. Steppers and commit clamp to this value.</td>\n</tr>\n<tr>\n<td><code>Step</code></td>\n<td><code>Decimal</code></td>\n<td>Amount added / subtracted by the steppers and <code>ArrowUp</code> / <code>ArrowDown</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Hint</code></td>\n<td>Optional helper text rendered below the field (hidden when empty).</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Change</code></td>\n<td>Fired when the committed value changes (after debounce while typing, or immediately on blur / step).</td>\n<td><code>Identifier</code> (<code>Text</code>), <code>Value</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>Clear</code></td>\n<td>Fired when the clear control is activated (click or <code>Enter</code>).</td>\n<td><code>Identifier</code> (<code>Text</code>)</td>\n</tr>\n<tr>\n<td><code>EnterKey</code></td>\n<td>Fired when <code>Enter</code> is pressed, after any pending change has been flushed.</td>\n<td><code>Identifier</code> (<code>Text</code>), <code>Value</code> (<code>Text</code>)</td>\n</tr>\n</tbody></table>","skeleton":"<h6>Overview</h6>\n<p>A loading placeholder that shows animated skeleton shapes while data is being fetched, then reveals the real <code>Content</code> once loading completes. It can render any combination of a pulsing circle, a spinner, and a stack of bars, configured through the <code>Display</code> structure.</p>\n<p>While <code>IsWaiting</code> is <code>True</code> the placeholders pulse. When <code>IsWaiting</code> becomes <code>False</code>, each placeholder plays a staggered &quot;destruction&quot; animation and is removed; after the last one resolves, the <code>Content</code> placeholder is shown in its place. Placeholders render in a fixed order: circle, then spinner, then bars.</p>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Display</code></td>\n<td><code>Structure</code></td>\n<td>Controls which loading placeholders are rendered. See the <code>Display</code> structure below.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the component.</td>\n</tr>\n<tr>\n<td><code>IsWaiting</code></td>\n<td><code>Boolean</code></td>\n<td>While <code>true</code>, placeholders are shown. Setting it to <code>false</code> animates them out and reveals <code>Content</code>.</td>\n</tr>\n<tr>\n<td><code>Width</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireScale\"><code>SapphireScale</code></a></td>\n<td>Sets the width of the skeleton container.</td>\n</tr>\n</tbody></table>\n<hr><h6><code>Display</code> structure</h6>\n<p>An object describing which placeholders to render. Rendered in order: circle, loading, then bars.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Bars</code></td>\n<td><code>Integer</code></td>\n<td>Number of bar placeholders to render. When <code>&gt; 0</code>, renders that many bars with decreasing widths.</td>\n</tr>\n<tr>\n<td><code>Circle</code></td>\n<td><code>Text</code></td>\n<td>Size of a circular placeholder. Accepts <code>s</code>, <code>m</code>, or <code>l</code>; any other value (or empty) renders no circle.</td>\n</tr>\n<tr>\n<td><code>Loading</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>true</code>, renders a spinner loader.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Content</code></td>\n<td>Element to be displayed as content after <code>IsWaiting</code> becomes false.</td>\n</tr>\n</tbody></table>","toast":"<h6>Overview</h6>\n<p>A global toast notification service (<code>SapphireRWALibrary.Toast</code>) that shows stacked messages at the top centre of the screen. It is not a screen widget: call it from client logic to create or clear notifications.</p>\n<ul>\n<li>Toasts are mounted into <code>#transitionContainer</code> inside a fixed <code>.toast</code> stack (centred, below the top of the viewport). Newer messages are prepended above older ones.</li>\n<li>Each toast shows a type icon, optional <code>Title</code>, <code>Body</code> (HTML), an optional close affordance, and a progress bar that tracks <code>TimeToLive</code>.</li>\n<li>Supported types: <code>alert-info</code>, <code>alert-error</code>, <code>alert-success</code>, <code>alert-warning</code>. Unknown types fall back to the info icon. The legacy value <code>Entities.Alert.Info</code> is normalised to <code>alert-info</code>.</li>\n<li>When <code>TimeToLive</code> is greater than <code>0</code>, the progress bar runs for that many seconds and then dismisses the toast. When it is <code>0</code>, the toast stays until the user dismisses it.</li>\n<li>Clicking the toast (or its close control when <code>HasClose</code> is <code>True</code>) starts the removal animation. When the last toast is gone, the container is removed.</li>\n</ul>\n<hr><h6>Actions</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CreateToastNotification</code></td>\n<td>Creates and shows a toast from a message object <code>ToastMessage</code>.</td>\n</tr>\n<tr>\n<td><code>ClearToastNotifications</code></td>\n<td>Removes all toasts and tears down the toast container immediately.</td>\n</tr>\n</tbody></table>\n<hr><h6>Message structure (<code>ToastMessage</code>)</h6>\n<p>Passed to <code>CreateToastNotification</code>.</p>\n<table>\n<thead>\n<tr>\n<th>Property</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Body</code></td>\n<td><code>Text</code></td>\n<td>Main content. Rendered as HTML (supports links and markup).</td>\n</tr>\n<tr>\n<td><code>HasClose</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, shows a close (<code>x</code>) icon. The whole toast is still dismissible by click either way.</td>\n</tr>\n<tr>\n<td><code>TimeToLive</code></td>\n<td><code>Integer</code></td>\n<td>Auto-dismiss duration in seconds. Drives the progress bar. <code>0</code> means no auto-dismiss (toast stays until clicked or cleared).</td>\n</tr>\n<tr>\n<td><code>Title</code></td>\n<td><code>Text</code></td>\n<td>Bold title above the body. Empty string hides meaningful title text.</td>\n</tr>\n<tr>\n<td><code>Type</code></td>\n<td><code>Text</code></td>\n<td>Visual variant: <code>alert-info</code>, <code>alert-error</code>, <code>alert-success</code>, or <code>alert-warning</code>. Icons and colours follow the type.</td>\n</tr>\n</tbody></table>","weekdaypicker":"<h6>Overview</h6>\n<p>A compact control that renders seven rounded weekday buttons for picking one or more days of the week. Labels are locale-aware, selection is capped by a target count, and the stable day values follow ISO weekday numbering regardless of display order.</p>\n<ul>\n<li>The component generates all seven buttons into the <code>.weekdaypicker</code> root; there is no content placeholder.</li>\n<li>Day values are always ISO-style integers: <code>1</code> = Monday … <code>7</code> = Sunday. <code>WeekStart</code> only changes the visual order of the buttons.</li>\n<li>Button labels use <code>Intl.DateTimeFormat</code> with <code>WeekDayFormat</code> (<code>narrow</code>, <code>short</code>, or <code>long</code>). Each button also has a <code>title</code> with the <code>long</code> weekday name for hover clarity.</li>\n<li><code>Locale</code> drives formatting. When it is empty / nullish, the component falls back to <code>SapphireRWALibrary.State.locale</code>, then to <code>en-US</code>.</li>\n<li>The user can select up to <code>SelectableCount</code> days. When that count is reached, unselected days become disabled; deselecting a selected day re-enables them.</li>\n<li><code>SelectableCount</code> updates from outside (via <code>parametersChanged</code>) are applied immediately: selection is clamped to the new cap and disabled state is refreshed.</li>\n<li><code>Selected</code> seeds or updates the active days from outside (via init / <code>parametersChanged</code>). Extra values beyond <code>SelectableCount</code> are ignored.</li>\n<li><code>Change</code> fires on every user toggle (select or deselect), passing <code>Identifier</code> and the current selected ISO days (in selection order).</li>\n<li><code>Density</code> controls button size. Only <code>Compact</code> and <code>Default</code> from <a href=\"/RW_DesignSystem/StaticEntities#SapphireDensity\"><code>SapphireDensity</code></a> are supported; other density values are not applied.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Density</code></td>\n<td><a href=\"/RW_DesignSystem/StaticEntities#SapphireDensity\"><code>SapphireDensity</code></a></td>\n<td>Visual density of the day buttons. Supported values: <code>Compact</code> (smaller buttons) and <code>Default</code> (standard size). Other <a href=\"/RW_DesignSystem/StaticEntities#SapphireDensity\"><code>SapphireDensity</code></a> entries (<code>Dense</code>, <code>Comfortable</code>) are not used by this component.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables all interaction. Disabled pickers ignore clicks and use disabled styling (<code>data-enabled</code> on the root is typically set by the platform).</td>\n</tr>\n<tr>\n<td><code>Locale</code></td>\n<td><code>Text</code></td>\n<td>BCP 47 locale code (for example <code>en-US</code>, <code>pt-PT</code>) used for weekday labels. Empty / nullish falls back to <code>SapphireRWALibrary.State.locale</code>, then <code>en-US</code>.</td>\n</tr>\n<tr>\n<td><code>SelectableCount</code></td>\n<td><code>Integer</code></td>\n<td>Maximum number of weekdays the user can select (<code>0</code>–<code>7</code>). When the current selection reaches this count, remaining unselected days are disabled until one is deselected. Updates via <code>parametersChanged</code> clamp the selection and refresh disabled state.</td>\n</tr>\n<tr>\n<td><code>Selected</code></td>\n<td><code>Text</code></td>\n<td>Currently selected ISO weekdays. Accepts a JSON array string such as <code>&quot;[1,3,5]&quot;</code> (same shape as the serialized selection), or an equivalent list of integers <code>1</code>–<code>7</code>. Values outside that range are ignored.</td>\n</tr>\n<tr>\n<td><code>WeekDayFormat</code></td>\n<td><code>Text</code></td>\n<td>Visible label length passed to <code>Intl</code>. Supported values: <code>narrow</code> (e.g. <code>M</code>), <code>short</code> (e.g. <code>Mon</code>), <code>long</code> (e.g. <code>Monday</code>). Invalid values default to <code>short</code>. Hover <code>title</code> always uses <code>long</code>.</td>\n</tr>\n<tr>\n<td><code>WeekStart</code></td>\n<td><code>Integer</code></td>\n<td>First day shown in the row, using ISO numbering (<code>1</code> = Monday … <code>7</code> = Sunday). Only affects display order; selected values stay ISO-stable. Invalid values default to <code>1</code>.</td>\n</tr>\n</tbody></table>\n<hr><h6>Events</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n<th>Arguments</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>Change</code></td>\n<td>Fired on every user select or deselect, with the current selection (in selection order).</td>\n<td><code>Identifier</code> (<code>Text</code>), <code>Days</code> (<code>Integer List</code>)</td>\n</tr>\n</tbody></table>","printdocument":"<h6>Overview</h6>\n<p>A print-preview pattern: a trigger button that opens a modal popup containing the document at <code>DocumentURL</code> in an iframe. Use it when you need to preview (and optionally print) a generated document without leaving the current screen.</p>\n<ul>\n<li>The pattern renders as an inline print button labelled with <code>LabelPrint</code>. Clicking it opens a <code>SapphirePopupContent</code> popup themed <code>printdocument</code>.</li>\n<li>The popup body hosts an iframe (<code>printpreview</code>) that loads <code>DocumentURL</code> full-size, with no border. Body overflow is left to the iframe so the document scrolls inside the frame rather than the popup.</li>\n<li>A close button in the popup dismisses it and returns to the host screen. The button must have the <code>btn-close</code> CSS class.</li>\n<li>The popup footer is the same three-column grid as <code>SapphirePopupContent</code> (<code>FooterLeft</code> / <code>FooterCenter</code> / <code>FooterRight</code>). Put extra actions there (for example Download). The footer is hidden when all three placeholders are empty.</li>\n<li>When <code>Enabled</code> is <code>False</code>, the trigger button is disabled and the popup cannot be opened from it.</li>\n</ul>\n<hr><h6>Input parameters</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Type</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>CloseOnEsc</code></td>\n<td><code>Boolean</code></td>\n<td>When <code>True</code>, pressing <code>Escape</code> fires the <code>Close</code> event.</td>\n</tr>\n<tr>\n<td><code>DocumentURL</code></td>\n<td><code>Text</code></td>\n<td>URL of the document loaded in the print-preview iframe.</td>\n</tr>\n<tr>\n<td><code>Enabled</code></td>\n<td><code>Boolean</code></td>\n<td>Enables or disables the print trigger button. When <code>False</code>, the button ignores clicks.</td>\n</tr>\n<tr>\n<td><code>LabelPrint</code></td>\n<td><code>Text</code></td>\n<td>Label for the button that triggers the Print Preview popup.</td>\n</tr>\n</tbody></table>\n<hr><h6>Placeholders</h6>\n<table>\n<thead>\n<tr>\n<th>Name</th>\n<th>Description</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>FooterLeft</code></td>\n<td>Left-aligned content in the print-preview popup footer.</td>\n</tr>\n<tr>\n<td><code>FooterCenter</code></td>\n<td>Center-aligned content in the print-preview popup footer.</td>\n</tr>\n<tr>\n<td><code>FooterRight</code></td>\n<td>Right-aligned content in the print-preview popup footer.</td>\n</tr>\n</tbody></table>"};
	function normalize(name) {
		return String(name == null ? '' : name).toLowerCase().replace(/[^a-z0-9]/g, '');
	}
	function SapphireRWADocumentation(name) {
		if (!(this instanceof SapphireRWADocumentation)) return new SapphireRWADocumentation(name);
		this.name = name;
		this.html = DOCS[normalize(name)] || '';
	}
	SapphireRWADocumentation.has = function (name) { return normalize(name) in DOCS; };
	SapphireRWADocumentation.names = function () { return Object.keys(DOCS); };
	window.SapphireRWADocumentation = SapphireRWADocumentation;
})();
